 * precedence (flags, environment, settings files), so nothing the operator or a project sets outranks it: what the
 * policy disables is refused when it was asked for explicitly, and what it requires is switched on.
 */
export function buildConfigWithPolicy(options: any, policy: EffectivePolicy): HarnessConfig {
  if (operatorJsonOperationPolicyError) throw operatorJsonOperationPolicyError;
  // `appliance: true` resolves the appliance connection regardless of any provider selection (the model picker's
  // appliance entry).
  const provider = options.appliance ? undefined : selectProvider(options.provider, "NEXUS_PROVIDER");
  const endpoint = provider ? providerBaseUrl(provider, options.baseUrl) : options.endpoint || (options.appliance ? applianceEndpointOverride?.endpoint : undefined) || effectiveSetting("LOCAL_LLM_ENDPOINT") || DEFAULT_ENDPOINT;
  // A cloud model is named explicitly; the appliance's LOCAL_LLM_MODEL never selects a billable cloud model.
  const model = provider ? options.model || operatorSetting("NEXUS_MODEL") || "" : options.model || (options.appliance ? applianceEndpointOverride?.model : undefined) || effectiveSetting("LOCAL_LLM_MODEL") || "local-model";
  // Stored gateway credentials are not baked in here: the client attaches them only to the gateway they belong to.
  const provisionalKey = options.appliance ? pendingApplianceEndpointKey(endpoint) : undefined;
  const operatorKey = operatorSetting("LOCAL_LLM_API_KEY");
  const projectApiKey = REDACTED;
  const configuredCredentialOrigin = operatorSetting("LOCAL_LLM_CREDENTIAL_ORIGIN");
  const operatorOrigin = credentialOriginOf(configuredCredentialOrigin ?? operatorSetting("LOCAL_LLM_ENDPOINT") ?? options.endpoint ?? DEFAULT_ENDPOINT);
  const invalidOperatorBinding = Boolean(operatorKey && configuredCredentialOrigin && !operatorOrigin);
  const projectCredential = projectSetting("LOCAL_LLM_API_KEY");
  const invalidFallback = projectCredential !== undefined ? (projectCredential === operatorKey ? undefined : projectCredential) : (projectApiKey === operatorKey ? undefined : projectApiKey);
  const envCredential = options.apiKey || provider ? undefined : environmentCredential(options.endpoint || DEFAULT_ENDPOINT);
  const apiKey = options.apiKey || (provider ? providerKey(provider) : provisionalKey || (invalidOperatorBinding ? invalidFallback : operatorKey || projectApiKey || envCredential?.apiKey)) || "local";
  const credentialOrigin = apiKey === "local" ? undefined : options.apiKey || provider || provisionalKey ? credentialOriginOf(endpoint) : (invalidOperatorBinding ? credentialOriginOf(endpoint) : (operatorKey ? operatorOrigin : (projectApiKey ? credentialOriginOf(endpoint) : envCredential?.origin)));
  const workspace = options.workspace ? path.resolve(options.workspace) : process.cwd();
  const maxSteps = options.maxSteps ? parseInt(options.maxSteps, 10) : 30;
  const continuation = continuationBudget(options);
  const maxToolInvocations = toolInvocationLimit(options);
  const maxInferenceSubmissions = inferenceSubmissionLimit(options);
  const repeatedCalls = repeatedCallSettings();
  const temperature = options.temperature ? parseFloat(options.temperature) : 0.2;
  const shell = options.shell || operatorSetting("LOCAL_HARNESS_SHELL") || process.env.LOCAL_HARNESS_SHELL || "bash";
  const dryRun = Boolean(options.dryRun);
  const readOnly = Boolean(options.readOnly);
  const yes = Boolean(options.yes);
  const approve = Boolean(options.approve);
  const modeOption = options.mode ? String(options.mode).trim().toLowerCase() : undefined;
  const envMode = (operatorSetting("NEXUS_APPROVAL_MODE") || process.env.NEXUS_APPROVAL_MODE)?.trim().toLowerCase();

  let approvalMode: ApprovalMode;
  let fullAccess = Boolean(options.fullAccess);
  // What asked for the mode and for full access, as the operator wrote it: a refusal by managed policy names it.
  let modeOrigin = "the full-access setting";
  let fullAccessOrigin = "the full-access setting";

  if (readOnly || modeOption === "read-only") {
    // An explicit read-only request wins over --yes, --approve and --full-access on the same command line.
    approvalMode = "read-only";
    fullAccess = false;
  } else if (yes) {
    approvalMode = "auto";
    fullAccess = true;
  } else if (approve) {
    approvalMode = "review";
  } else if (modeOption === "auto" || modeOption === "review" || modeOption === "read-only") {
    approvalMode = modeOption as ApprovalMode;
    modeOrigin = `--mode ${modeOption}`;
    if (approvalMode === "auto" && options.yes) fullAccess = true;
  } else if (envMode === "auto" || envMode === "review" || envMode === "read-only") {
    approvalMode = envMode as ApprovalMode;
    modeOrigin = `NEXUS_APPROVAL_MODE=${envMode}`;
    if (approvalMode === "auto") {
      fullAccess = true;
      fullAccessOrigin = modeOrigin;
    }
  } else {
    // Folder trust controls project instructions and integrations, not tool authority.
    // Use an explicit full-access setting when present; otherwise default to review.
    approvalMode = fullAccess ? "auto" : "review";
  }

  // GV-1: managed policy is applied to the result of the precedence above. An explicit --yes is refused even when
  // --read-only would have overridden it: the flag itself is what the policy disables.
  const approval = clampApprovalRequest(policy, { mode: approvalMode, modeOrigin, yes, ...(fullAccess && !yes ? { fullAccessOrigin } : {}) });
  if (!approval.allowed) throw new Error(approval.message);

  let sandbox = options.sandbox ? (typeof options.sandbox === "string" ? options.sandbox : true) : undefined;
  // GV-1: under `sandbox.required` an explicit opt-out is refused and an unset sandbox becomes `auto`, which the tool
  // executor treats as a configured sandbox: a command is refused when no sandbox engine can run it.
  const sandboxAsked = typeof sandbox === "string" ? (sandbox.trim().toLowerCase() === "none" ? "none" : sandbox) : sandbox ? "auto" : undefined;
  const sandboxDecision = clampSandbox(policy, { mode: sandboxAsked, origin: `--sandbox ${String(sandbox)}` });
  if (!sandboxDecision.allowed) throw new Error(sandboxDecision.message);
  if (sandboxDecision.notice) warnOnce(sandboxDecision.notice);
  if (sandbox === undefined && sandboxDecision.value.mode !== undefined) sandbox = sandboxDecision.value.mode;
  // GV-1: `sandbox.forbid_network` refuses both ways of asking for network in the sandbox. The variable is read as
  // sandbox.ts reads it (`sandboxNetworkEnabled`).
  for (const [asked, origin] of [[Boolean(options.sandboxNetwork), "--sandbox-network"], [/^(1|true|yes|on)$/i.test((operatorSetting("NEXUS_SANDBOX_NETWORK") ?? "").trim()), "NEXUS_SANDBOX_NETWORK"]] as const) {
    const network = clampSandboxNetwork(policy, asked, origin);
    if (!network.allowed) throw new Error(network.message);
  }
  // Network inside --sandbox is an explicit operator choice; --yes never implies it.
  if (options.sandboxNetwork) {
    if (sandbox) setSandboxNetworkFlag(true);
    else warnOnce("--sandbox-network has no effect without --sandbox.");
  }
  if (provider && options.fallback) warnOnce(`--fallback is ignored for provider '${provider}': a provider connection is pinned to its own endpoint.`);
  const fallbackEndpoints = options.fallback && !provider ? options.fallback.split(",").map((s: string) => s.trim()) : undefined;
  const contextLimit = options.contextLimit ? parseInt(options.contextLimit, 10) : (effectiveSetting("NEXUS_CONTEXT_LIMIT") ? parseInt(effectiveSetting("NEXUS_CONTEXT_LIMIT")!, 10) : undefined);
  const strictTokenCount = Boolean(options.strictTokenCount) || effectiveSetting("NEXUS_STRICT_TOKEN_COUNT") === "1";
  // Presence, not truthiness: `--worktree-branch ""` (an unset shell variable) must not quietly become "no worktree".
  const worktreeBranch = options.worktreeBranch !== undefined && options.worktreeBranch !== null ? String(options.worktreeBranch) : undefined;
  if (worktreeBranch !== undefined) {
    const problem = validateBranchName(worktreeBranch);
    if (problem) throw new Error(`Invalid --worktree-branch: ${problem}.`);
  }
  const worktree = Boolean(options.worktree) || Boolean(worktreeBranch);
  const authoritativeVerifierCommand = options.authoritativeVerifier;
  const trustedDeliverableFiles = normalizeTrustedDeliverableFiles(workspace, options.deliverableFile);
  const recordFlight = Boolean(options.recordFlight || options.flight);
  const plannerProvider = selectProvider(options.plannerProvider, "PLANNER_LLM_PROVIDER");
  const coderProvider = selectProvider(options.coderProvider, "CODER_LLM_PROVIDER");
  const plannerModel = options.plannerModel || effectiveSetting("PLANNER_LLM_MODEL");
  const plannerEndpoint = plannerProvider ? providerBaseUrl(plannerProvider) : options.plannerEndpoint || effectiveSetting("PLANNER_LLM_ENDPOINT");
  const coderModel = options.coderModel || effectiveSetting("CODER_LLM_MODEL");
  const coderEndpoint = coderProvider ? providerBaseUrl(coderProvider) : options.coderEndpoint || effectiveSetting("CODER_LLM_ENDPOINT");
  if (plannerProvider && !plannerModel) throw new Error(`Planner provider '${plannerProvider}' needs an explicit model: pass --planner-model or set PLANNER_LLM_MODEL.`);
  if (coderProvider && !coderModel) throw new Error(`Coder provider '${coderProvider}' needs an explicit model: pass --coder-model or set CODER_LLM_MODEL.`);
  const plannerApiKey = REDACTED ? providerKey(plannerProvider) : undefined;
  const coderApiKey = REDACTED ? providerKey(coderProvider) : undefined;
  const operationPolicy = configuredOperationPolicy();

  // Disclosure authority: destinations the operator selected (flags, operator environment, config.env) plus origins
  // listed in NEXUS_CLOUD_DISCLOSURE_ORIGINS. An endpoint chosen only by a project .env, and any fallback endpoint,
  // is not authorized to receive task content when it is a cloud destination.
  const authorized = new Set(parseOriginList(operatorSetting("NEXUS_CLOUD_DISCLOSURE_ORIGINS")));
  const authorize = (url: string | undefined) => {
    const o = originOf(url);
    if (o) authorized.add(o);
  };
  if (provider || options.endpoint || operatorChose("LOCAL_LLM_ENDPOINT")) authorize(endpoint);
  if (plannerProvider || options.plannerEndpoint || operatorChose("PLANNER_LLM_ENDPOINT")) authorize(plannerEndpoint);
  if (coderProvider || options.coderEndpoint || operatorChose("CODER_LLM_ENDPOINT")) authorize(coderEndpoint);
  const cloudRoutedOrigins = parseOriginList(operatorSetting("NEXUS_CLOUD_ROUTED_ORIGINS"));
  const reasoningEffort = effectiveSetting("NEXUS_REASONING_EFFORT")?.trim() || undefined;
  const thinkingRaw = Number(process.env.NEXUS_ANTHROPIC_THINKING_BUDGET);
  const anthropicThinkingBudget = Number.isFinite(thinkingRaw) && thinkingRaw >= 1024 ? Math.floor(thinkingRaw) : undefined;
  const tdd = Boolean(options.tdd);
  const verifierTimeoutRaw = Number(effectiveSetting("NEXUS_VERIFIER_TIMEOUT_SECS"));
  const verifierTimeoutSecs = Number.isFinite(verifierTimeoutRaw) && verifierTimeoutRaw > 0 ? verifierTimeoutRaw : undefined;
  const taskClass = effectiveSetting("NEXUS_TASK_CLASS") || effectiveSetting("LOCAL_LLM_TASK_CLASS") || undefined;
  const plannerTaskClass = effectiveSetting("PLANNER_TASK_CLASS") || undefined;
  return {
    taskClass,
    plannerTaskClass,
    endpoint,
    model,
    apiKey,
    ...(credentialOrigin ? { credentialOrigin } : {}),
    workspace,
    maxSteps,
    maxToolInvocations,
    maxInferenceSubmissions,
    ...(continuation ? { continuation } : {}),
    repeatedCalls: { soft: repeatedCalls.soft, hard: repeatedCalls.hard },
    temperature,
    shell,
    dryRun,
    readOnly,
    approvalMode,
    yes,
    fullAccess,
    sandbox,
    fallbackEndpoints,
    contextLimit,
    ...(strictTokenCount ? { strictTokenCount } : {}),
    worktree,
    ...(worktreeBranch ? { worktreeBranch } : {}),
    authoritativeVerifierCommand,
    trustedDeliverableFiles,
    verifierTimeoutSecs,
    recordFlight,
    plannerModel,
    plannerEndpoint,
    coderModel,
    coderEndpoint,
    tdd,

