    assert.deepEqual(parseSandboxValue("none"), { engine: "none" });
    for (const engine of ["auto", "bwrap", "docker"] as const) assert.deepEqual(parseSandboxValue(engine), { engine });
    for (const profile of SANDBOX_PROFILE_NAMES) {
